// DeclarationList is the Go interface backing the Gom sort DeclarationList.
type DeclarationList interface {
	sharedobjects.Term
	isDeclarationList()
}

// ConcDeclarationDeclarationList is the term type for the alternative `concDeclaration(...)` of sort DeclarationList.
type ConcDeclarationDeclarationList struct {
	Slots []Declaration
	hash  uint32
}

func (*ConcDeclarationDeclarationList) isDeclarationList() {}

func (t *ConcDeclarationDeclarationList) Hash() uint32 { return t.hash }

func (t *ConcDeclarationDeclarationList) Equivalent(other sharedobjects.Term) bool {
	o, ok := other.(*ConcDeclarationDeclarationList)
	if !ok {
		return false
	}
	if len(t.Slots) != len(o.Slots) {
		return false
	}
	for i := range t.Slots {
		if t.Slots[i] != o.Slots[i] {
			return false
		}
	}
	return true
}

func (t *ConcDeclarationDeclarationList) Duplicate() sharedobjects.Term {
	cp := append([]Declaration(nil), t.Slots...)
	return &ConcDeclarationDeclarationList{Slots: cp, hash: t.hash}
}

func (t *ConcDeclarationDeclarationList) String() string {
	parts := make([]string, len(t.Slots))
	for i, v := range t.Slots {
		parts[i] = fmt.Sprintf("%v", v)
	}
	return "concDeclaration" + "(" + strings.Join(parts, ",") + ")"
}

// MakeConcDeclaration builds the canonical (shared) concDeclaration term.
func MakeConcDeclaration(args ...Declaration) DeclarationList {
	hashes := make([]uint32, 0, len(args))
	for _, a := range args {
		hashes = append(hashes, a.Hash())
	}
	proto := &ConcDeclarationDeclarationList{Slots: args, hash: sharedobjects.MixSymbol(sharedobjects.StringHash("concDeclaration"), hashes)}
	return factory.Build(proto).(*ConcDeclarationDeclarationList)
}
